@startuml

class Bookmaker {}

class Bettor {
  + name : string
  + balance : float
}

class Race {
  + raceId : int
  + startTime : datetime
}

class Runner {
  + runnerId : int
  + horseName : string
}

class Jockey {
  + name : string
}

class Bet {
  + amount : float
  + odds : float
}

Bookmaker "1" -- "*" Bettor
Bettor "1" -- "*" Bet
Race "1" -- "1..*" Runner
Runner "1" -- "1" Jockey
Bet "*" -- "1" Race
Bet "*" -- "1" Runner
Race "1" -- "0..1" Runner : winner

@enduml

